def build():
    # Validate SMLE
    assert len(SMLE_RAW) == 100, f"Expected 100 SMLE topics, got {len(SMLE_RAW)}"
    for t in SMLE_RAW:
        assert t[1] in TAXONOMY_SUBJECTS, f"Invalid subject {t[1]} in {t[0]}"
        assert t[2] in TAXONOMY_SYSTEMS, f"Invalid system {t[2]} in {t[0]}"
        assert t[5].startswith("https://"), f"Invalid url {t[5]} in {t[0]}"

    # Validate HAAD
    assert len(HAAD_RAW) == 100, f"Expected 100 HAAD topics, got {len(HAAD_RAW)}"
    for t in HAAD_RAW:
        assert t[1] in TAXONOMY_SUBJECTS, f"Invalid subject {t[1]} in {t[0]}"
        assert t[2] in TAXONOMY_SYSTEMS, f"Invalid system {t[2]} in {t[0]}"
        assert t[5].startswith("https://"), f"Invalid url {t[5]} in {t[0]}"

    # Validate UHS
    assert len(UHS_RAW) == 100, f"Expected 100 UHS topics, got {len(UHS_RAW)}"
    for t in UHS_RAW:
        assert t[1] in TAXONOMY_SUBJECTS, f"Invalid subject {t[1]} in {t[0]}"
        assert t[2] in TAXONOMY_SYSTEMS, f"Invalid system {t[2]} in {t[0]}"
        assert t[5].startswith("https://"), f"Invalid url {t[5]} in {t[0]}"

    out_file = os.path.join(os.path.dirname(__file__), "mega43_topics_b.py")
    with open(out_file, "w", encoding="utf-8") as f:
        f.write('"""Generated topics for Mega-Batch 43 Part B (SMLE, HAAD, UHS)"""\n\n')
        f.write(f"SMLE_TOPICS = {repr(SMLE_RAW)}\n\n")
        f.write(f"HAAD_TOPICS = {repr(HAAD_RAW)}\n\n")
        f.write(f"UHS_TOPICS = {repr(UHS_RAW)}\n")
    print(f"Successfully generated {out_file} with {len(SMLE_RAW)} SMLE, {len(HAAD_RAW)} HAAD, and {len(UHS_RAW)} UHS topics.")

if __name__ == "__main__":
    build()
